[Form]
public class TFMTranslations extends FormRun
{
    int counter = 0;
    boolean usesLabelFile;
    TFMTranslations mobTransRecord;
    FormStringControl callerCtrl;
    XmlDocument appCfgXmlDoc;

}

public void init()
{
    super();

    if(element.args() && element.args().record())
    {
        mobTransRecord = element.args().record() as TFMTranslations;
    }
    else if(element.args() && element.isCreateRequestedFromPreviousPage(element.args()))
    {
        callerCtrl = element.args().callerFormControl() as FormStringControl;
        FormButtonControl_NewLabel.clicked();
    }
    else
    {
        mobTransRecord = null;
    }
    TFMDocApplicationConfiguration docConf = new TFMDocApplicationConfiguration();
    str appCfgContentStr = docConf.getApplicationConfigurationContent();
    appCfgXmlDoc = XmlDocument::newXml(appCfgContentStr);
}

private boolean isCreateRequestedFromPreviousPage(Args args)
{
    return args.parmEnum() == 2;
}

/// <summary>
/// Find all the places of the usage of the translation. It will look through the application configuration xml to find the usage.
/// </summary>
/// <param name = "_xPath">The xpath of how to find where the translation is begin used.</param>
/// <returns></returns>
protected Map findAllRelatedContent(str _xPath)
{
    Map foundXmlElements = new Map(Types::String, Types::Class);

    XmlNodeList nodes = appCfgXmlDoc.selectNodes(_xPath);
    if(nodes)
    {
        XmlNode node = nodes.nextNode();
        XmlNode parent;
        XmlElement parentElement;
        XmlElement lastNodeWithIdAttribute;
        while(node)
        {
            // find the last parent Xml element with an id
            parent = node;
            while(parent)
            {
                if(parent as XmlElement)
                {
                    // the parenet xml element is found. Now we can jump to the parent element instead of the node.
                    parentElement = parent;

                    if(parentElement.hasAttribute('id'))
                    {
                        lastNodeWithIdAttribute = parentElement;
                    }
                }
                parent = parent.parentNode();
            }
            if(lastNodeWithIdAttribute)
            {
                foundXmlElements.add(lastNodeWithIdAttribute.getAttribute('id'), lastNodeWithIdAttribute);
            }
            node = nodes.nextNode(); // find the next match in the configuration content.
        }
    }
    return foundXmlElements;
}

/// <summary>
///
/// </summary>
public void executeQuery()
{
    this.queryBuildDataSource().sortClear();
    this.queryBuildDataSource().addSortField(fieldNum(SysDataBaseLog,RecId),SortOrder::Descending);

    super();

    if(mobTransRecord)
    {
        TFMTranslationsDS_ds.positionToRecord(mobTransRecord);
    }
}

/// <summary>
///
/// </summary>
public void selectionChanged()
{
    SysTranslationHelper helper;
    container conLanguage;
    container languages;
    TFMTranslationLines line;
    LanguageId languageId;
    Label label;
    int i = 0;
    str extractedLabel;
    str html;
    str languageHeaderLabel = "@SYS95066";
    str translationHeaderLabel = "@SYS21154";
    Set addedLanuages = new Set(Types::String);
    str formattedLabelId;
    str xPath;
    Map elementsFoundAttributes;
    MapEnumerator setEnum;
    str labelForPlacesUsedHeader;
    str labelForPlacesUsedId;
    str labelForPlacesUsedValue;

    super();
    helper = new SysTranslationHelper(tableNum(TFMTranslations), tableNum(TFMTranslationLines));
    conLanguage = SysTranslationDetailHelper::populateLanguageDropDown(helper.getTranslationTableId(), helper.getLanguageFieldId());
    languages = conPeek(conLanguage, 3);

    TFMHtmlViewerCtrl_translations.parmHtml('');

    if(!TFMTranslationsDS.LabelString && !TFMTranslationsDS.LabelId)
    {
        return;
    }

    html = '<table class=\'none\' style=\'border: 1px solid #bbb; width: 600px; \'>';
    html += '<thead style=\'background: #eee; \'>';
    html += '<tr><th style=\'padding: 5px;border: 1px solid #bbb; text-align: left; width: 30%;\'>' + languageHeaderLabel + '</th><th style=\'padding: 5px\'; border: 1px solid #bbb>' + translationHeaderLabel + '</th></tr>';
    html += '</thead>';
    html += '<tbody>';

    usesLabelFile = strLen(TFMTranslationsDS.LabelString) > 0;

    if(conLen(languages) < 5)
    {
        languages += SystemParameters::getSystemLanguageId();
    }

    for (i=5; i <= conlen(languages); i++)
    {
        languageId = conPeek(languages, i);
        label = new Label(languageId);

        line = TFMTranslationLines::find(TFMTranslationsDS.RecId, languageId, false);
        if(usesLabelFile)
        {
            extractedLabel = (line.RecId) ? line.Translation : label.extractString(TFMTranslationsDS.LabelString);
            html += '<tr><td style=\'padding: 5px; border-top: 1px solid #bbb; border-right: 1px solid #bbb; \'>' + languageId + '</td><td style=\'border-top: 1px solid #bbb; padding: 5px\';">' + extractedLabel + '</td></tr>';
            addedLanuages.add(languageId);
        }
        else if(!line.RecId && LanguageTable::exist(languageId))
        {
            TFMTranslationLinesDS_ds.create(false);
            TFMTranslationLinesDS.Language = languageId;
        }

        i++;
    }

    if(!usesLabelFile)
    {
        while select line where line.TranslationHeader == TFMTranslationsDS.RecId
        {
            if(!addedLanuages.in(line.Language))
            {
                html += '<tr><td style=\'padding: 5px; border-top: 1px solid #bbb; border-right: 1px solid #bbb; \'>' + line.Language + '</td><td style=\'border-top: 1px solid #bbb; padding: 5px\';">' + line.Translation + '</td></tr>';
            }
        }
    }

    // Add the Usage of the translations
    html += '</tbody></table><br/>';

    formattedLabelId = TFMTranslationProvider::getTranslationIdFormmattedForDevice(TFMTranslationsDS.LabelId);
    xPath = '//*[contains(text(),"'+ formattedLabelId +'") or @*[contains(., "'+ formattedLabelId +'")]]';
    elementsFoundAttributes = element.findAllRelatedContent(xPath);
    setEnum = elementsFoundAttributes.getEnumerator();
    labelForPlacesUsedHeader = "@TFM:UsageoftheTranslation";
    labelForPlacesUsedId = "@TFM:Type";
    labelForPlacesUsedValue = "@TFM:Usedin";

    html += '<div style="text-transform: uppercase; font-weight: 800;padding-bottom: 8px;">' + labelForPlacesUsedHeader + '</div>';
    html += '<table class=\'none\' style=\'border: 1px solid #bbb; width: 600px; \'>';
    html += '<thead style=\'background: #eee; \'>';
    html += '<tr><th style=\'padding: 5px;border: 1px solid #bbb; text-align: left; width: 30%;\'>' + labelForPlacesUsedId + '</th><th style=\'padding: 5px\'; border: 1px solid #bbb>' + labelForPlacesUsedValue + '</th></tr>';
    html += '</thead>';
    html += '<tbody>';

    while(setEnum.moveNext())
    {
        html += '<tr><td style=\'padding: 5px; border-top: 1px solid #bbb; border-right: 1px solid #bbb; \'>' + setEnum.currentValue().name() + '</td><td style=\'border-top: 1px solid #bbb; padding: 5px\';">' + setEnum.currentValue().attributes().getNamedItem('id').text() + '</td></tr>';
    }

    html += '</thead>';
    html += '<tbody>';

    TFMHtmlViewerCtrl_translations.parmHtml(html);
}

public void executeQuery()
{
    QueryBuildDataSource  queryBuildDataSource;
    queryBuildDataSource = this.query().dataSourceName(TFMTranslationLinesDS_ds.name());
    queryBuildDataSource.clearRanges();
    queryBuildDataSource.addRange(fieldnum(TFMTranslationLines, TranslationHeader)).value(queryValue(TFMTranslationsDS.RecId));
    super();
}

/// <summary>
///
/// </summary>
/// <returns></returns>
public boolean validateWrite()
{
    boolean ret;

    TFMTranslationLinesDS.TranslationHeader = TFMTranslationsDS.RecId;
    ret = super();

    return ret;
}

/// <summary>
///
/// </summary>
/// <returns></returns>
public boolean validateDelete()
{
    boolean ret;
    LanguageId orgLanguage = SystemParameters::getSystemLanguageId();
    if(usesLabelFile || orgLanguage != TFMTranslationLinesDS.Language)
    {
        ret = super();
    }
    else
    {
        info("@TFM:Thesystemlanguagemaynotbedeleted");
        ret = false;
    }

    return ret;
}

/// <summary>
///
/// </summary>
/// <param name = "_record"></param>
/// <param name = "_options"></param>
public void displayOption(Common _record, FormRowDisplayOption _options)
{
    TFMTranslationLines lines = _record;
    if(lines.Language == SystemParameters::getSystemLanguageId())
    {
        _options.backColor(System.Drawing.Color::WhiteSmoke.ToArgb());

    } 

    super(_record, _options);

}

/// <summary>
///
/// </summary>
public void executeQuery()
{
    QueryBuildDataSource  queryBuildDataSource;
    queryBuildDataSource = this.query().dataSourceName(TFMTranslationLookupDS_ds.name());
    queryBuildDataSource.clearRanges();
    queryBuildDataSource.addGroupByField(fieldnum(TFMTranslationLabelIdLookupTable, LabelFile));
    super();
}

/// <summary>
///
/// </summary>
public void clicked()
{
    Args    args;
    FormRun formRun;
    str     lId;
    Common  tableToUpdate;


    super();

    //Call the form directly.
    args = new Args(formStr(TFMCreateTranslationForm));

    formRun = New FormRun(args);
    formRun.init();
    formRun.run();
    formRun.wait();

    if(!formRun.cancelled())
    {
        TFMTranslationsDS_ds.research();
        TFMTranslationsDS_ds.setPosition(0);

        if(callerCtrl)
        {
            lId = element.TFMTranslationsDS.LabelId;

            // if the caller field has a datasource we need to update that datasource instead of setting the text.
            if(callerCtrl.dataSourceObject())
            {
                tableToUpdate = callerCtrl.dataSourceObject().cursor();
                ttsbegin;
                tableToUpdate.selectForUpdate(true);
                tableToUpdate.setFieldValue(fieldId2Name(tableToUpdate.TableId, callerCtrl.dataField()), lId);
                tableToUpdate.update();
                ttscommit;
                callerCtrl.dataSourceObject().reread();
                callerCtrl.dataSourceObject().refresh();
                callerCtrl.formRun().redraw();
            } 
            else
            {
                callerCtrl.text(lId);
                callerCtrl.modified();
            }
        }
    }

    element.args().parmEnum(0); // to make sure we are not treating the code in the same way again.
}

/// <summary>
/// Suggest translation for empty translation lines.
/// </summary>
public void clicked()
{
    TFMTranslationLines line;
    str orgLanguageTranslation;
    str lineTranslation;
    boolean wasUpdated;

    LanguageId orgLanguage = SystemParameters::getSystemLanguageId();
    super();

    // find original translation value
    select firstonly line where line.TranslationHeader == TFMTranslationsDS.RecId && line.Language == orgLanguage;

    if(!line.RecId && usesLabelFile)
    {
        Label label = new Label(orgLanguage);
        orgLanguageTranslation = label.extractString(TFMTranslationsDS.LabelString);
    }
    else if (line.RecId)
    {
        orgLanguageTranslation = line.Translation;
    }

    if(orgLanguageTranslation)
    {
        // suggest translations for empty translation lines
        while select forupdate line where line.TranslationHeader == TFMTranslationsDS.RecId
        {
            if(!line.Translation)
            {
                lineTranslation = TFMTranslationProvider::getAITranslation(orgLanguageTranslation, orgLanguage, line.Language, TFMTranslationsDS_Description.text());
                line.Translation = lineTranslation;
                ttsbegin;
                line.write();
                wasUpdated = true;
                ttscommit;
            }
        }
    }

    if(wasUpdated)
    {
        TFMTranslationLinesDS_ds.research(true);
    }
}
